-- JPAC Guitar 50-module rollout preflight. READ ONLY.
begin transaction read only;
with manifest as (
 select * from jsonb_to_recordset('[{"title":"Guitar Basics: Holding Your Guitar","num":1,"level":1,"sort":1},{"title":"First Chords: A, D, and E","num":2,"level":1,"sort":2},{"title":"Strumming Patterns Basics","num":3,"level":1,"sort":3},{"title":"12-Bar Blues Introduction","num":4,"level":1,"sort":4},{"title":"Chord Heroes: E, G, and C","num":5,"level":1,"sort":5},{"title":"R\u0026B Groove: Two-Chord Jam","num":6,"level":1,"sort":6},{"title":"Pop Song Power: Your First Verse","num":7,"level":1,"sort":7},{"title":"Rock Power: Intro to Power Chords","num":8,"level":1,"sort":8},{"title":"Ear Buddy: Playing by Listening","num":9,"level":1,"sort":9},{"title":"Creativity Sprint: Write a Rock Riff","num":10,"level":1,"sort":10},{"title":"Capstone Rehearsal \u0026 Polish","num":11,"level":1,"sort":11},{"title":"Showtime! Beginner Capstone","num":12,"level":1,"sort":12},{"title":"Power Chords \u0026 Rock Foundations","num":1,"level":2,"sort":13},{"title":"12-Bar Blues Pattern","num":2,"level":2,"sort":14},{"title":"Hammer-ons and Pull-offs","num":3,"level":2,"sort":15},{"title":"String Bending Techniques","num":4,"level":2,"sort":16},{"title":"Intro to Soloing: The Pentatonic Scale","num":5,"level":2,"sort":17},{"title":"Rock Expression: String Bending \u0026 Vibrato","num":6,"level":2,"sort":18},{"title":"Reading Guitar Tablature (Tabs)","num":7,"level":2,"sort":19},{"title":"Classic Blues Licks \u0026 Turnarounds","num":8,"level":2,"sort":20},{"title":"Writing Your First Rock Riff","num":9,"level":2,"sort":21},{"title":"The \"Four Chords of Pop\"","num":10,"level":2,"sort":22},{"title":"R\u0026B Soloing with Double Stops","num":11,"level":2,"sort":23},{"title":"Level Capstone: Perform a Full Song","num":12,"level":2,"sort":24},{"title":"Capo Usage and Transposition","num":13,"level":2,"sort":25},{"title":"Advanced Fingerpicking","num":14,"level":2,"sort":26},{"title":"The Major Scale \u0026 The Fretboard","num":1,"level":3,"sort":27},{"title":"Sweep Picking Arpeggios","num":2,"level":3,"sort":28},{"title":"Advanced Rock Techniques: Tapping","num":3,"level":3,"sort":29},{"title":"Complex Pop \u0026 R\u0026B Chords (9ths, 11ths)","num":4,"level":3,"sort":30},{"title":"Practical Music Theory for Guitarists","num":5,"level":3,"sort":31},{"title":"Improvisation Strategies","num":6,"level":3,"sort":32},{"title":"Composing a Guitar Solo","num":7,"level":3,"sort":33},{"title":"Jazz-Blues Fusion","num":8,"level":3,"sort":34},{"title":"Advanced Rhythm Guitar: Funk \u0026 R\u0026B","num":9,"level":3,"sort":35},{"title":"Using Effects Pedals","num":10,"level":3,"sort":36},{"title":"Ear Training for Guitarists","num":11,"level":3,"sort":37},{"title":"Level Capstone: Write \u0026 Record an Original","num":12,"level":3,"sort":38},{"title":"Harmonic Minor Scale Applications","num":1,"level":4,"sort":39},{"title":"Advanced Harmony for the Jazz Guitarist","num":2,"level":4,"sort":40},{"title":"Shred Techniques: Sweep \u0026 Economy Picking","num":3,"level":4,"sort":41},{"title":"Neo-Soul \u0026 Modern R\u0026B Guitar","num":4,"level":4,"sort":42},{"title":"The Circle of Fifths","num":5,"level":4,"sort":43},{"title":"Transcription \u0026 Analysis","num":6,"level":4,"sort":44},{"title":"Developing Your Artistic Voice","num":7,"level":4,"sort":45},{"title":"Studio Recording Techniques","num":8,"level":4,"sort":46},{"title":"Live Performance Strategies","num":9,"level":4,"sort":47},{"title":"Capstone: Write and Record an Original","num":10,"level":4,"sort":48},{"title":"Arranging for Guitar","num":11,"level":4,"sort":49},{"title":"Final Capstone: Produce a 3-Song EP","num":12,"level":4,"sort":50}]'::jsonb) as x(level int,num int,sort int,title text)
), guitar as (
 select count(*)::int n,(array_agg(id order by id::text))[1] id from public.courses where slug='guitar'
), sdi as (
 select count(*) filter(where (select count(*) from regexp_matches(regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g'),'m\.status=''published''','g'))=2 and strpos(regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g'),'m.status<>''archived''')=0)::int n
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('jpac_sync_enrollment_progress','jpac_enforce_canonical_enrollment_progress')
), canonical_trigger as (
 select count(*)::int n from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='enrollments' and t.tgname='enrollments_enforce_canonical_progress' and not t.tgisinternal and t.tgenabled<>'D'
), level_conflicts as (
 select count(*)::int n from public.course_levels l join public.courses c on c.id=l.course_id where c.slug='guitar' and (l.level_number not between 1 and 4 or l.title is distinct from (array['Beginner','Intermediate','Advanced','Master'])[l.level_number] or l.status<>'draft' or l.approved_by is not null or l.approved_at is not null)
), module_conflicts as (
 select count(*)::int n from manifest e join public.courses c on c.slug='guitar' left join public.course_levels l on l.course_id=c.id and l.level_number=e.level join public.course_modules m on m.course_id=c.id and (m.sort_order=e.sort or (m.course_level_id=l.id and m.level_module_number=e.num))
 where m.course_level_id is distinct from l.id or m.level_module_number is distinct from e.num or m.sort_order is distinct from e.sort or m.title is distinct from e.title or m.status<>'draft' or m.core_xp<>625 or m.intro_core_xp<>50 or m.video_core_xp<>100 or m.assignment_core_xp<>350 or m.mastery_core_xp<>125 or m.core_unlock_threshold<>438 or m.lab_tool_id is not null or m.active_instructional_media_id is not null or m.primary_video_url is not null or m.approved_by is not null or m.approved_at is not null
), sort_conflicts as (
 select count(*)::int n from public.course_modules m join public.courses c on c.id=m.course_id left join manifest e on e.sort=m.sort_order where c.slug='guitar' and m.sort_order between 1 and 50 and (e.sort is null or m.title is distinct from e.title)
), child_conflicts as (
 select count(*)::int n from manifest e join public.courses c on c.slug='guitar' join public.course_levels l on l.course_id=c.id and l.level_number=e.level join public.course_modules m on m.course_level_id=l.id and m.level_module_number=e.num
 where (exists(select 1 from public.lessons where module_id=m.id) or exists(select 1 from public.activities where module_id=m.id))
 and ((select count(*) from public.lessons where module_id=m.id)<>3 or (select count(*) from public.activities where module_id=m.id)<>2 or (select count(*) from public.activities where module_id=m.id and status='draft' and activity_type='practice' and not required and xp_reward=0 and xp_type='bonus')<>1 or (select count(*) from public.activities where module_id=m.id and status='draft' and activity_type='performance' and required and xp_reward=350 and xp_type='core')<>1)
), deps as (
 select (select count(*) from public.enrollments e join public.courses c on c.id=e.course_id where c.slug='guitar')+(select count(*) from public.submissions s join public.activities a on a.id=s.activity_id join public.courses c on c.id=a.course_id where c.slug='guitar')+(select count(*) from public.lesson_progress p join public.lessons l on l.id=p.lesson_id join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id where c.slug='guitar')+(select count(*) from public.activity_progress p join public.activities a on a.id=p.activity_id join public.courses c on c.id=a.course_id where c.slug='guitar')+(select count(*) from public.practice_logs p join public.activities a on a.id=p.activity_id join public.courses c on c.id=a.course_id where c.slug='guitar')+(select count(*) from public.xp_ledger x join public.courses c on c.id=x.course_id where c.slug='guitar')+(select count(*) from public.certificates x join public.courses c on c.id=x.course_id where c.slug='guitar')+(select count(*) from public.portfolio_projects p join public.activities a on a.id=p.activity_id join public.courses c on c.id=a.course_id where c.slug='guitar') n
), baselines as (
 select 'SINGING_CURRICULUM_BASELINE' code,md5(coalesce(string_agg(v,E'\\n' order by v),'')) details from (
  select m.id||':'||m.status||':'||m.title v from public.course_modules m join public.courses c on c.id=m.course_id where c.slug='singing'
  union all select l.id||':'||l.status||':'||l.title from public.lessons l join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id where c.slug='singing'
  union all select a.id||':'||a.status||':'||a.title from public.activities a join public.courses c on c.id=a.course_id where c.slug='singing') q
 union all
 select 'PIANO_CURRICULUM_BASELINE',md5(coalesce(string_agg(v,E'\\n' order by v),'')) from (
  select m.id||':'||m.status||':'||m.title v from public.course_modules m join public.courses c on c.id=m.course_id where c.slug='piano'
  union all select l.id||':'||l.status||':'||l.title from public.lessons l join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id where c.slug='piano'
  union all select a.id||':'||a.status||':'||a.title from public.activities a join public.courses c on c.id=a.course_id where c.slug='piano') q
 union all
 select 'STUDENT_STATE_BASELINE',jsonb_build_object('enrollments',(select count(*) from public.enrollments),'lesson_progress',(select count(*) from public.lesson_progress),'activity_progress',(select count(*) from public.activity_progress),'practice_logs',(select count(*) from public.practice_logs),'submissions',(select count(*) from public.submissions),'xp_ledger',(select count(*) from public.xp_ledger),'certificates',(select count(*) from public.certificates),'portfolio_projects',(select count(*) from public.portfolio_projects))::text
 union all
 select 'ASSIGNMENT_SWAP_BASELINE',jsonb_build_object('definition_hash',(select md5(coalesce(string_agg(p.proname||':'||pg_get_functiondef(p.oid),E'\\n' order by p.proname),'')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('curriculum_swap_module_assignment_v1','curriculum_rollback_assignment_swap_v1')),'audit_rows',(select count(*) from public.curriculum_assignment_swap_operations))::text
),
findings as (
 select 'IDENTITY' section,'GUITAR_IDENTITY' code,case when n=1 then 'PASS' else 'BLOCK' end result,format('canonical guitar course rows=%s; id=%s',n,coalesce(id::text,'NULL')) details from guitar
 union all select 'DRAFT_ISOLATION','SAFE_DRAFT_ISOLATION',case when s.n=2 and t.n=1 then 'PASS' else 'BLOCK' end,format('published-only functions=%s/2; trigger=%s',s.n,t.n) from sdi s cross join canonical_trigger t
 union all select 'COMPATIBILITY','LEVEL_COMPATIBILITY',case when n=0 then 'PASS' else 'BLOCK' end,format('incompatible levels=%s',n) from level_conflicts
 union all select 'COMPATIBILITY','MODULE_COMPATIBILITY',case when n=0 then 'PASS' else 'BLOCK' end,format('incompatible modules=%s',n) from module_conflicts
 union all select 'COMPATIBILITY','GLOBAL_SORT_ORDER',case when n=0 then 'PASS' else 'BLOCK' end,format('incompatible global sort rows=%s',n) from sort_conflicts
 union all select 'COMPATIBILITY','CHILD_COMPATIBILITY',case when n=0 then 'PASS' else 'BLOCK' end,format('incompatible populated module children=%s',n) from child_conflicts
 union all select 'EVIDENCE','GUITAR_DEPENDENCIES',case when n=0 then 'PASS' else 'BLOCK' end,format('Guitar evidence/student dependencies=%s',n) from deps
 union all select 'MANIFEST','MANIFEST_COUNTS',case when count(*)=50 and count(*) filter(where level=1)=12 and count(*) filter(where level=2)=14 and count(*) filter(where level=3)=12 and count(*) filter(where level=4)=12 and min(sort)=1 and max(sort)=50 and count(distinct sort)=50 then 'PASS' else 'BLOCK' end,format('modules=%s; L1=%s; L2=%s; L3=%s; L4=%s; sort=%s-%s',count(*),count(*) filter(where level=1),count(*) filter(where level=2),count(*) filter(where level=3),count(*) filter(where level=4),min(sort),max(sort)) from manifest
 union all select 'PRESERVATION',code,'INFO','Capture and compare after migration: '||details from baselines
), blockers as(select count(*) filter(where result='BLOCK')::int n from findings)
select section as report_section,code,result,details from findings
union all select 'READINESS','BLOCKERS',case when n=0 then 'PASS' else 'BLOCK' end,format('blocking findings=%s',n) from blockers
union all select 'READINESS','OVERALL',case when n=0 then 'PASS' else 'BLOCK' end,case when n=0 then 'PASS: READY FOR GUITAR DRAFT ROLLOUT MIGRATION' else 'BLOCK: DO NOT RUN MIGRATION' end from blockers
order by report_section,code;
rollback;
